create table public.profiles (id uuid primary key references auth.users on delete cascade, username text unique not null, display_name text, avatar_path text, avatar_url text, locale text default 'nl', updated_at timestamptz default now());
create table public.encrypted_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, item_type text not null check (item_type in ('journal','checkin','settings','audio')), ciphertext text not null, nonce text not null, key_version int not null default 1, updated_at timestamptz default now());
create table public.devices (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, platform text not null, push_token text not null, updated_at timestamptz default now(), unique(user_id,push_token));
alter table public.profiles enable row level security; alter table public.encrypted_items enable row level security; alter table public.devices enable row level security;
create policy "own profile" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "own encrypted data" on public.encrypted_items for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own devices" on public.devices for all using (auth.uid()=user_id) with check (auth.uid()=user_id);

create table if not exists public.peer_invites (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, code text unique not null, expires_at timestamptz not null, used_by uuid references auth.users, created_at timestamptz default now());
create table if not exists public.peer_connections (id uuid primary key default gen_random_uuid(), user_a uuid not null references auth.users on delete cascade, user_b uuid not null references auth.users on delete cascade, created_at timestamptz default now(), check(user_a<>user_b));
create table if not exists public.peer_messages (id uuid primary key default gen_random_uuid(), connection_id uuid not null references public.peer_connections on delete cascade, sender_id uuid not null references auth.users on delete cascade, body text not null check(char_length(body)<=500), created_at timestamptz default now());
alter table public.peer_invites enable row level security; alter table public.peer_connections enable row level security; alter table public.peer_messages enable row level security;
create policy "own invites" on public.peer_invites for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "own connections" on public.peer_connections for select using(auth.uid() in(user_a,user_b));
create policy "peer messages read" on public.peer_messages for select using(exists(select 1 from public.peer_connections c where c.id=connection_id and auth.uid() in(c.user_a,c.user_b)));
create policy "peer messages send" on public.peer_messages for insert with check(auth.uid()=sender_id and exists(select 1 from public.peer_connections c where c.id=connection_id and auth.uid() in(c.user_a,c.user_b)));
create or replace function public.accept_peer_invite(invite_code text) returns uuid language plpgsql security definer set search_path=public as $$ declare inv peer_invites; cid uuid; begin select * into inv from peer_invites where code=upper(invite_code) and used_by is null and expires_at>now() for update;if inv.id is null then raise exception 'Ongeldige of verlopen code';end if;if inv.owner_id=auth.uid() then raise exception 'Je kunt niet met jezelf koppelen';end if;insert into peer_connections(user_a,user_b) values(inv.owner_id,auth.uid()) returning id into cid;update peer_invites set used_by=auth.uid() where id=inv.id;return cid;end $$;
create or replace function public.my_peer_connections() returns table(connection_id uuid,peer_name text) language sql security definer set search_path=public as $$ select c.id,coalesce(p.display_name,p.username,'Steunmaatje') from peer_connections c join profiles p on p.id=case when c.user_a=auth.uid() then c.user_b else c.user_a end where auth.uid() in(c.user_a,c.user_b) $$;
grant execute on function public.accept_peer_invite(text) to authenticated;grant execute on function public.my_peer_connections() to authenticated;
alter publication supabase_realtime add table public.peer_messages;
